"""Render docs/learning/interview-prep.md as a print-ready HTML page (then Edge prints it to PDF)."""
import re, sys, html
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent / "pylib"))
import markdown

SRC = Path(sys.argv[1])
OUT = Path(sys.argv[2])

text = SRC.read_text(encoding="utf-8")
text = text[text.index("\n## ") + 1:]                       # drop the on-screen intro
text = re.sub(r"<details>\s*<summary>Answer</summary>\s*", "", text)
text = text.replace("</details>", "")
text = re.sub(r"\[([^\]]+)\]\([^)]+\)", r"\1", text)          # links -> plain text on paper

# Number every question and collect the checklist.
sections, n = [], 0
def number(m):
    global n
    n += 1
    sections[-1][1].append((n, m.group(1)))
    return f"### Q{n}. {m.group(1)}"
out_lines = []
for line in text.splitlines():
    if line.startswith("## "):
        sections.append((line[3:], []))
    m = re.match(r"### (.+)", line)
    out_lines.append(number(m) if m else line)
text = "\n".join(out_lines)
text = re.sub(r"^Notes?: (.+)$", r'<p class="notes">Study notes: \1</p>', text, flags=re.M)

body = markdown.markdown(text, extensions=["tables", "fenced_code"])
# Wrap each question + answer so it doesn't split awkwardly across pages.
body = re.sub(r"(<h3>.*?)(?=<h3>|<h2>|\Z)", r'<section class="qa">\1</section>', body, flags=re.S)

def inline(s):
    return re.sub(r"`([^`]+)`", r"<code>\1</code>", html.escape(s, quote=False))
checklist = "".join(
    f"<h4>{html.escape(name)}</h4><ol start='{qs[0][0]}'>"
    + "".join(f"<li><span class='box'></span>{inline(q)}</li>" for _, q in qs) + "</ol>"
    for name, qs in sections if qs
)

page = f"""<!doctype html><html><head><meta charset="utf-8"><title>Interview Prep Sheet</title>
<style>
@page {{ size: Letter; margin: 0.6in 0.65in; }}
body {{ font: 10.5pt/1.42 Georgia, 'Times New Roman', serif; color: #111; background: #fff; }}
h1 {{ font: 700 26pt/1.1 'Segoe UI', Arial, sans-serif; margin: 0 0 6pt; }}
h2 {{ font: 700 15pt 'Segoe UI', Arial, sans-serif; border-bottom: 2px solid #111; padding-bottom: 3pt;
      margin: 22pt 0 8pt; break-after: avoid; }}
h3 {{ font: 700 11.5pt 'Segoe UI', Arial, sans-serif; margin: 14pt 0 4pt; break-after: avoid; }}
h4 {{ font: 700 10.5pt 'Segoe UI', Arial, sans-serif; margin: 10pt 0 2pt; }}
code, pre {{ font-family: Consolas, 'Courier New', monospace; font-size: 9pt; }}
code {{ background: #f0f0f0; padding: 0 2px; }}
pre {{ background: #f4f4f4; border: 1px solid #ccc; padding: 6pt; white-space: pre-wrap; break-inside: avoid; }}
pre code {{ background: none; }}
table {{ border-collapse: collapse; margin: 6pt 0; font-size: 9.5pt; break-inside: avoid; }}
th, td {{ border: 1px solid #999; padding: 2pt 5pt; text-align: left; vertical-align: top; }}
th {{ background: #e8e8e8; }}
p, ul, ol {{ margin: 4pt 0; }}
.qa {{ break-inside: avoid-page; border-left: 3px solid #bbb; padding-left: 9pt; margin-bottom: 10pt; }}
.notes {{ font: 8.5pt 'Segoe UI', Arial, sans-serif; color: #555; }}
.cover {{ break-after: page; }}
.meta {{ font: 12pt 'Segoe UI', Arial, sans-serif; margin: 0 0 14pt; }}
.howto li {{ margin-bottom: 3pt; }}
.checklist {{ break-after: page; }}
.checklist ol {{ padding-left: 22pt; }}
.checklist li {{ margin: 2pt 0; }}
.box {{ display: inline-block; width: 9pt; height: 9pt; border: 1px solid #111; margin-right: 6pt;
        vertical-align: -1pt; }}
</style></head><body>
<div class="cover">
<h1>Nuuly Inventory API: Interview Prep Sheet</h1>
<p class="meta"><b>Panel:</b> Thursday, October 8, 2026, 2:00 pm, two hours on Zoom<br>
Hour 1: Architect + Senior Software Engineer &nbsp;·&nbsp; Hour 2: Architect + Software Engineer</p>
<h3>How to use this sheet</h3>
<ol class="howto">
<li><b>Page 2 is the quiz.</b> Read each question, answer it <i>out loud</i>, then check the full answer.</li>
<li>Tick the box only when you answered it without peeking. Mark misses with a dot and redo them the next day.</li>
<li>For every answer, be ready to <b>point at the code</b>: which file, which line, which test proves it.</li>
<li>Expect follow-ups of the form “how would this change if...”. The Architecture section is where those start.</li>
</ol>
<p>Generated from <code>docs/learning/interview-prep.md</code>. {n} questions.</p>
</div>
<div class="checklist"><h2>Question checklist</h2>{checklist}</div>
{body}
</body></html>"""
OUT.write_text(page, encoding="utf-8")
print(f"{n} questions -> {OUT}")

